optimized_semantic_plan.program:
BASE := SCAN_TABLE(NASA_ASRS, incidents.csv, [incident_id,text_file,local_time_of_day,flight_phase]) -> FILTER(local_time_of_day='1201-1800' AND (flight_phase CONTAINS 'Approach' OR flight_phase CONTAINS 'Landing'));
ENV := SCAN_TABLE(NASA_ASRS, environment_attributes.csv, [incident_id,attribute,value]) -> FILTER(attribute='flight_conditions' AND value IN ('IMC','Marginal','Mixed'));
WITH_ENV := JOIN(left=BASE, right=ENV, condition=incident_id equality);
RESULTS := SCAN_TABLE(NASA_ASRS, events.csv, [incident_id,event_type,label]) -> FILTER(event_type='result' AND label IN ('Flight Crew Executed Go Around / Missed Approach','Air Traffic Control Issued New Clearance'));
STRUCTURED := JOIN(left=WITH_ENV, right=RESULTS, condition=incident_id equality);
STRUCTURED -> SCAN_DOCS(NASA_ASRS, selector=STRUCTURED.text_file) -> SEM_FILTER('weather or visibility caused the target result') -> SEM_FILTER('traffic, runway occupancy, or equipment was not the primary cause') -> GROUP_BY([flight_conditions,recorded_result], incident_count=COUNT_DISTINCT(incident_id))

BASE := SCAN_TABLE(NASA_ASRS, incidents.csv, [incident_id,text_file,primary_problem]) -> FILTER(primary_problem='Human Factors');
FACTORS := SCAN_TABLE(NASA_ASRS, person_factors.csv, [incident_id,factor_type,value]) -> FILTER(factor_type='human_factors' AND value CONTAINS ANY OF ['Communication Breakdown','Workload','Confusion','Situational Awareness']);
CANDIDATES := JOIN(left=BASE, right=FACTORS, condition=incident_id equality) -> GROUP_BY([incident_id,text_file], recorded_factors=COLLECT(value));
EXTRACTED := CANDIDATES -> SCAN_DOCS(NASA_ASRS, selector=CANDIDATES.text_file) -> SEM_EXTRACT('causally contributing human-factor phrases, actor, and effect');
VOCAB := FACTORS -> PROJECT([value]) -> DEDUP([value]);
SEM_JOIN(left=EXTRACTED, right=VOCAB, instruction='semantic factor match compatible with the incident structured factor') -> GROUP_BY([canonical_human_factor], incident_count=COUNT_DISTINCT(incident_id))

INCIDENTS := SCAN_TABLE(NASA_ASRS, incidents.csv, [incident_id,text_file,primary_problem])
  -> FILTER(primary_problem='Aircraft');
STATUS := SCAN_TABLE(NASA_ASRS, aircraft_attributes.csv, [incident_id,attribute,value])
  -> FILTER(attribute IN ('maintenance_status_records_complete','maintenance_status_required_correct_doc_on_board'))
  -> GROUP_BY([incident_id], {records_complete:MAX_IF(value,attribute='maintenance_status_records_complete'),correct_document_on_board:MAX_IF(value,attribute='maintenance_status_required_correct_doc_on_board')});
PROBLEMS := SCAN_TABLE(NASA_ASRS, components.csv, [incident_id,attribute,value])
  -> FILTER(attribute='problem')
  -> GROUP_BY([incident_id], {structured_problems:COLLECT(value)});
WITH_STATUS := JOIN(left=INCIDENTS, right=STATUS, join_type=inner, condition=INCIDENTS.incident_id = STATUS.incident_id);
STRUCTURED := JOIN(left=WITH_STATUS, right=PROBLEMS, join_type=inner, condition=WITH_STATUS.incident_id = PROBLEMS.incident_id);
EXTRACTED := STRUCTURED
  -> SCAN_DOCS(NASA_ASRS, selector=STRUCTURED.text_file, [incident_id,text])
  -> SEM_EXTRACT('Determine whether this is an actual maintenance-documentation problem rather than a mechanical discrepancy alone. Emit is_actual_documentation_issue; when true, assign documentation_issue_type from {incomplete_or_inaccurate_logbook,missing_or_incomplete_work_card,incorrect_or_incomplete_mel_procedure,missing_required_document,release_or_signoff_error} and extract the affected item in at most six words.', {incident_id:string,is_actual_documentation_issue:boolean,documentation_issue_type:string,affected_item:string}, {incident_id,text});
EXTRACTED
  -> FILTER(is_actual_documentation_issue=TRUE)
  -> GROUP_BY([documentation_issue_type,records_complete,correct_document_on_board], {incident_count:COUNT_DISTINCT(incident_id),canonical_affected_item:MODE(affected_item)})
  -> ORDER_BY([incident_count DESC,documentation_issue_type ASC,records_complete ASC,correct_document_on_board ASC])
  -> LIMIT(15)
  -> PROJECT([rank=ROW_NUMBER(),documentation_issue_type,records_complete,correct_document_on_board,incident_count,canonical_affected_item])

EQUIPMENT_EVENTS := SCAN_TABLE(NASA_ASRS, events.csv, [incident_id, event_type, label])
  -> FILTER(label CONTAINS 'Aircraft Equipment Problem')
  -> DEDUP([incident_id]);
INCIDENTS := SCAN_TABLE(NASA_ASRS, incidents.csv, [incident_id, text_file]);
EQUIPMENT_INCIDENTS := JOIN(left=EQUIPMENT_EVENTS, right=INCIDENTS, join_type=inner, condition=EQUIPMENT_EVENTS.incident_id = INCIDENTS.incident_id);
NARRATIVE_COMPONENTS := EQUIPMENT_INCIDENTS
  -> SCAN_DOCS(NASA_ASRS, selector=EQUIPMENT_INCIDENTS.text_file, [incident_id, text])
  -> SEM_EXTRACT("Emit one row for each aircraft component actually involved in the reported problem. Extract narrative_component_term as used in the report and first_detection_cue in at most six words.", {incident_id:string, narrative_component_term:string, first_detection_cue:string}, {incident_id,text});
FREQUENT_TERMS := NARRATIVE_COMPONENTS
  -> GROUP_BY([narrative_component_term], {incident_count:COUNT_DISTINCT(incident_id)})
  -> FILTER(incident_count >= 5);
COMPONENT_VOCABULARY := SCAN_TABLE(NASA_ASRS, components.csv, [attribute, value])
  -> FILTER(attribute = 'aircraft_component')
  -> DEDUP([value]);
TERM_MATCHES := SEM_JOIN(left=FREQUENT_TERMS, right=COMPONENT_VOCABULARY, instruction="Match each narrative component term to a canonical component label when they denote the same component or a clear part-to-system relationship. Exact spelling and incident ID are not required and generic topical similarity is insufficient.", input_bindings_left={narrative_component_term}, input_bindings_right={canonical_component:value});
MATCHED_OCCURRENCES := JOIN(left=NARRATIVE_COMPONENTS, right=TERM_MATCHES, join_type=inner, condition=NARRATIVE_COMPONENTS.narrative_component_term = TERM_MATCHES.narrative_component_term);
MATCHED_OCCURRENCES
-> GROUP_BY([canonical_component,narrative_component_term], {incident_count:COUNT_DISTINCT(incident_id), most_common_detection_cue:MODE(first_detection_cue)})
-> ORDER_BY([incident_count DESC, canonical_component ASC, narrative_component_term ASC])
-> LIMIT(20)
-> PROJECT([rank=ROW_NUMBER(),canonical_component,narrative_component_term,incident_count,most_common_detection_cue])

BASE := SCAN_TABLE(NASA_ASRS, incidents.csv, [incident_id,text_file,local_time_of_day]) -> FILTER(local_time_of_day='1201-1800');
RESULTS := SCAN_TABLE(NASA_ASRS, events.csv, [incident_id,event_type,label]) -> FILTER(event_type='result' AND label IN ('Flight Crew Diverted','General Declared Emergency','Air Traffic Control Issued New Clearance')) -> GROUP_BY([incident_id], labels=COLLECT(label));
CANDIDATES := JOIN(left=BASE, right=RESULTS, condition=incident_id equality);
CANDIDATES -> SCAN_DOCS(NASA_ASRS, selector=CANDIDATES.text_file) -> SEM_FILTER('weather or visibility explicitly caused an operational decision') -> SEM_FILTER('exclude incidental weather and passenger-comfort-only turbulence') -> SEM_EXTRACT('one row per weather mechanism and recorded decision') -> GROUP_BY([weather_mechanism,recorded_decision], incident_count=COUNT_DISTINCT(incident_id)) -> ORDER_BY(incident_count DESC) -> LIMIT(20)

BASE := SCAN_TABLE(NASA_ASRS, incidents.csv, [incident_id,text_file,primary_problem]) -> FILTER(primary_problem='Aircraft');
COMP := SCAN_TABLE(NASA_ASRS, components.csv, [incident_id,attribute,value]) -> FILTER(attribute='aircraft_component' AND value CONTAINS ANY OF ['Pressurization','Pack','Bleed','Air Conditioning']) -> GROUP_BY([incident_id], components=COLLECT(value));
WITH_COMP := JOIN(left=BASE, right=COMP, condition=incident_id equality);
EVENTS := SCAN_TABLE(NASA_ASRS, events.csv, [incident_id,event_type,label]) -> FILTER(label='Flight Deck / Cabin / Aircraft Event Smoke / Fire / Fumes / Odor' OR label CONTAINS 'Aircraft Equipment Problem') -> GROUP_BY([incident_id], labels=COLLECT(label));
STRUCTURED := JOIN(left=WITH_COMP, right=EVENTS, condition=incident_id equality);
STRUCTURED -> SCAN_DOCS(NASA_ASRS, selector=STRUCTURED.text_file) -> SEM_FILTER('one clearly primary cause') -> SEM_FILTER('operational consequence beyond a maintenance record') -> SEM_EXTRACT('initiating condition, system, intervention, and outcome') -> SEM_CLASSIFY('primary cause category') -> GROUP_BY([cause_category], records=COLLECT(*)) -> SEM_AGGREGATE('canonical system and dominant outcome')

BASE := SCAN_TABLE(NASA_ASRS, incidents.csv, [incident_id,text_file,primary_problem]) -> FILTER(primary_problem='Aircraft');
MAINTENANCE := SCAN_TABLE(NASA_ASRS, aircraft_attributes.csv, [incident_id,attribute,value]) -> FILTER((attribute='maintenance_status_maintenance_deferred' OR attribute='maintenance_status_released_for_service') AND value='Y') -> GROUP_BY([incident_id], maintenance_flags=COLLECT(attribute)) -> PROJECT([incident_id,maintenance_status=CASE WHEN maintenance_flags CONTAINS 'maintenance_status_maintenance_deferred' AND maintenance_flags CONTAINS 'maintenance_status_released_for_service' THEN 'both' WHEN maintenance_flags CONTAINS 'maintenance_status_maintenance_deferred' THEN 'deferred' ELSE 'released_to_service' END]);
WITH_STATUS := JOIN(left=BASE, right=MAINTENANCE, condition=BASE.incident_id = MAINTENANCE.incident_id);
COMPONENTS := SCAN_TABLE(NASA_ASRS, components.csv, [incident_id,attribute,value]) -> FILTER(attribute IN ('aircraft_component','problem')) -> GROUP_BY([incident_id], structured_components=COLLECT_IF(value,attribute='aircraft_component'), structured_problems=COLLECT_IF(value,attribute='problem'));
STRUCTURED := JOIN(left=WITH_STATUS, right=COMPONENTS, condition=WITH_STATUS.incident_id = COMPONENTS.incident_id);
CHAINS := STRUCTURED -> SCAN_DOCS(NASA_ASRS, selector=STRUCTURED.text_file, [incident_id,text]) -> SEM_FILTER('explicitly connects an earlier maintenance deferral or release-to-service decision to a later component discrepancy') -> SEM_FILTER('clearly places discovery in before_departure, after_takeoff, or after_landing') -> SEM_EXTRACT('earlier decision, affected item, later discrepancy, operational effect, and normalized discovery phase') -> SEM_CLASSIFY('chain category', target_labels=[deferred_item_recurred,released_item_failed,incomplete_repair_or_signoff,maintenance_limitation_escalated]);
CHAINS -> GROUP_BY([maintenance_status,discovery_phase,chain_category], incident_count=COUNT_DISTINCT(incident_id), chain_records=COLLECT(affected_item,later_discrepancy,structured_components,structured_problems)) -> SEM_AGGREGATE('canonical affected item and recurring discrepancy, each at most six words') -> ORDER_BY([incident_count DESC,maintenance_status ASC,discovery_phase ASC,chain_category ASC]) -> LIMIT(12) -> PROJECT([rank=ROW_NUMBER(),maintenance_status,discovery_phase,chain_category,incident_count,canonical_affected_item,recurring_discrepancy])

LEFT := SCAN_TABLE(NASA_ASRS, incidents.csv AS L, [incident_id,incident_date,state_reference,locale_reference_type,primary_problem,text_file]);
RIGHT := SCAN_TABLE(NASA_ASRS, incidents.csv AS R, [incident_id,incident_date,state_reference,locale_reference_type,primary_problem,text_file]);
BLOCKED := JOIN(left=LEFT, right=RIGHT, condition=L.incident_id<R.incident_id AND date/state/locale/problem equality);
LEFT_IDS := BLOCKED -> PROJECT([incident_id=L.incident_id,text_file=L.text_file]) -> DEDUP([incident_id]) -> SCAN_DOCS(NASA_ASRS, selector=text_file) -> SEM_EXTRACT('normalized event signature for left incident');
RIGHT_IDS := BLOCKED -> PROJECT([incident_id=R.incident_id,text_file=R.text_file]) -> DEDUP([incident_id]) -> SCAN_DOCS(NASA_ASRS, selector=text_file) -> SEM_EXTRACT('normalized event signature for right incident');
LEFT_PAIRS := JOIN(left=BLOCKED, right=LEFT_IDS, condition=L.incident_id=LEFT_IDS.incident_id);
RIGHT_PAIRS := JOIN(left=BLOCKED, right=RIGHT_IDS, condition=R.incident_id=RIGHT_IDS.incident_id);
MATCHED := SEM_JOIN(left=LEFT_PAIRS, right=RIGHT_PAIRS, instruction='same blocked pair and same distinctive occurrence');
MATCHED -> ORDER_BY(incident_date DESC) -> LIMIT(20)

RESULTS := SCAN_TABLE(NASA_ASRS, events.csv, [incident_id,event_type,label]) -> FILTER(event_type='result' AND label IN ('General Flight Cancelled / Delayed','Flight Crew Returned To Departure Airport','General Maintenance Action')) -> GROUP_BY([incident_id], recorded_results=COLLECT(label));
INCIDENTS := SCAN_TABLE(NASA_ASRS, incidents.csv, [incident_id,text_file]);
CANDIDATES := JOIN(left=RESULTS, right=INCIDENTS, condition=incident_id equality) -> SCAN_DOCS(NASA_ASRS, selector=text_file);
PRIMARY := CANDIDATES -> SEM_FILTER('maintenance is the primary disruption driver');
EXTRACTED := PRIMARY -> SEM_EXTRACT('narrative affected item and maintenance-driver phrase') -> FILTER(narrative_affected_item IS NOT NULL AND narrative_affected_item <> '');
VOCAB := SCAN_TABLE(NASA_ASRS, components.csv, [attribute,value]) -> FILTER(attribute='aircraft_component') -> DEDUP([value]);
MATCHED := SEM_JOIN(left=EXTRACTED, right=VOCAB, instruction='synonym, abbreviation, or clear part-to-system component match');
STATUS := SCAN_TABLE(NASA_ASRS, aircraft_attributes.csv, [incident_id,attribute,value]) -> FILTER(attribute IN maintenance_status_fields) -> GROUP_BY([incident_id], status=COLLECT(attribute,value));
JOIN(left=MATCHED, right=STATUS, join_type=left, condition=incident_id equality) -> SEM_CLASSIFY('maintenance driver category') -> GROUP_BY([maintenance_driver,canonical_component], incident_count=COUNT_DISTINCT(incident_id)) -> ORDER_BY(incident_count DESC) -> LIMIT(15)

POLICY19 := SCAN_DOCS(CONTRACTEXHIBIT, all) -> SEM_FILTER('EX-19 policy prohibiting hedging, short sales, and pledging') -> SEM_EXTRACT('canonical policy-company key');
SUBS21 := SCAN_DOCS(CONTRACTEXHIBIT, all) -> SEM_FILTER('EX-21 subsidiary list with an identified parent') -> SEM_EXTRACT('canonical parent-company key and subsidiary count') -> GROUP_BY(company_key, MAX(subsidiary_count));
CLAW97 := SCAN_DOCS(CONTRACTEXHIBIT, all) -> SEM_FILTER('policy provides both restatement and misconduct recovery') -> SEM_FILTER('document is an EX-97 clawback policy') -> SEM_EXTRACT('canonical policy-company key, company, and covered-person category');
FIRST := JOIN(left=CLAW97, right=SUBS21, condition=CLAW97.company_key = SUBS21.company_key);
ALL_THREE := JOIN(left=FIRST, right=POLICY19, condition=FIRST.company_key = POLICY19.company_key);
ALL_THREE -> GROUP_BY([company, covered_person_category], subsidiary_count=MAX(subsidiary_count))

REPORTS := SCAN_DOCS(NHTSA, investigation_reports, [file_id,body]);
WITH_RECALLS := REPORTS -> SEM_EXTRACT('every normalized and deduplicated NHTSA recall number cited in the body') -> FILTER(LENGTH(cited_recall_numbers)>=1);
CLOSED := WITH_RECALLS -> SEM_FILTER('investigation is closed, concluded, or ended');
CLOSED -> SEM_CLASSIFY('primary defect topic') -> PROJECT([file_id,primary_topic,cited_recall_numbers])

COMPLAINTS := SCAN_TABLE(NHTSA, complaints, [complaint_id,vehicle_id,make,model,component_id,injury_count,death_count,summary_text]) -> FILTER(make='NISSAN' AND model='ALTIMA' AND component_id='AIRBAG' AND (injury_count>0 OR death_count>0));
AIRBAG_RECALLS := SCAN_DOCS(NHTSA, recalls, [campaign.number,vehicle.vehicle_id,component.component_id]) -> FILTER(component.component_id='AIRBAG') -> DEDUP([vehicle_id,campaign.number]);
COVERED_VEHICLES := AIRBAG_RECALLS -> PROJECT([vehicle_id]) -> DEDUP([vehicle_id]);
CANDIDATES := JOIN(left=COMPLAINTS, right=COVERED_VEHICLES, condition=COMPLAINTS.vehicle_id = COVERED_VEHICLES.vehicle_id);
QUALIFIED := CANDIDATES -> SEM_FILTER('airbag inflator rupture, explosion, shrapnel, or metal fragments causing injury') -> SEM_EXTRACT('short canonical airbag failure mode');
JOIN(left=QUALIFIED, right=AIRBAG_RECALLS, condition=QUALIFIED.vehicle_id = AIRBAG_RECALLS.vehicle_id) -> PROJECT([complaint_id,vehicle_id,campaign_number,airbag_failure_mode])

COMPLAINT_BASE := SCAN_TABLE(NHTSA, complaints, [complaint_id,make,component_id,summary_text]) -> FILTER(component_id='ADAS');
RECALL_BASE := SCAN_DOCS(NHTSA, recalls, [campaign.number,vehicle.make AS make,component.component_id,risk.defect_summary]) -> FILTER(component.component_id='ADAS');
COMPLAINT_MAKES := COMPLAINT_BASE -> PROJECT([make]) -> DEDUP([make]);
RECALL_MAKES := RECALL_BASE -> PROJECT([make]) -> DEDUP([make]);
COMMON_MAKES := JOIN(left=COMPLAINT_MAKES, right=RECALL_MAKES, condition=make equality) -> PROJECT([make]) -> DEDUP([make]);
COMPLAINTS := JOIN(left=COMPLAINT_BASE, right=COMMON_MAKES, condition=make equality) -> SEM_FILTER('phantom braking by a driver-assist system') -> GROUP_BY([make], phantom_braking_complaint_count=COUNT_DISTINCT(complaint_id));
RECALLS := JOIN(left=RECALL_BASE, right=COMMON_MAKES, condition=make equality) -> SEM_FILTER('automatic or driver-assist braking is the recall defect') -> GROUP_BY([make], matching_adas_recall_count=COUNT_DISTINCT(campaign.number));
JOIN(left=COMPLAINTS, right=RECALLS, condition=make equality) -> ORDER_BY(phantom_braking_complaint_count DESC, make ASC) -> LIMIT(4)

COMPLAINT_BASE := SCAN_TABLE(NHTSA, complaints, [complaint_id,make,vehicle_id,summary_text]) -> FILTER(make IN ['TOYOTA','HONDA']);
RECALL_BASE := SCAN_DOCS(NHTSA, recalls, [campaign.number,vehicle.vehicle_id AS vehicle_id,vehicle.make AS make,risk.defect_summary]) -> FILTER(vehicle.make IN ['TOYOTA','HONDA']);
COMPLAINT_KEYS := COMPLAINT_BASE -> PROJECT([vehicle_id]) -> DEDUP([vehicle_id]);
RECALL_KEYS := RECALL_BASE -> PROJECT([vehicle_id]) -> DEDUP([vehicle_id]);
COMMON_KEYS := JOIN(left=COMPLAINT_KEYS, right=RECALL_KEYS, condition=vehicle_id equality) -> PROJECT([vehicle_id]) -> DEDUP([vehicle_id]);
COMPLAINTS := JOIN(left=COMPLAINT_BASE, right=COMMON_KEYS, condition=vehicle_id equality) -> SEM_FILTER('severe safety event while the vehicle was being driven');
RECALLS := JOIN(left=RECALL_BASE, right=COMMON_KEYS, condition=vehicle_id equality) -> SEM_FILTER('safety-critical defect capable of crash, injury, fire, control loss, airbag or brake failure, or motive-power loss') -> DEDUP([campaign.number,vehicle_id]);
JOIN(left=COMPLAINTS, right=RECALLS, condition=vehicle_id equality) -> GROUP_BY([make], matched_complaint_count=COUNT_DISTINCT(complaint_id))

COMPLAINT_BASE := SCAN_TABLE(NHTSA, complaints, [complaint_id,make,model_year,summary_text]) -> FILTER(model_year IN [2023,2024,2025]);
RECALL_BASE := SCAN_DOCS(NHTSA, recalls, [campaign.number,vehicle.make AS make,campaign.report_received_date,risk.defect_summary,remedy.corrective_action]) -> FILTER(campaign.report_received_date BETWEEN '2023-01-01' AND '2025-12-31');
COMPLAINT_MAKES := COMPLAINT_BASE -> PROJECT([make]) -> DEDUP([make]);
RECALL_MAKES := RECALL_BASE -> PROJECT([make]) -> DEDUP([make]);
COMMON_MAKES := JOIN(left=COMPLAINT_MAKES, right=RECALL_MAKES, condition=make equality) -> PROJECT([make]) -> DEDUP([make]);
COMPLAINTS := JOIN(left=COMPLAINT_BASE, right=COMMON_MAKES, condition=make equality) -> SEM_FILTER('EV or hybrid battery, charging, BMS, electric-drive, high-voltage, hybrid-drivetrain, or control-software issue') -> GROUP_BY([make], ev_hybrid_complaint_count=COUNT_DISTINCT(complaint_id));
RECALLS := JOIN(left=RECALL_BASE, right=COMMON_MAKES, condition=make equality) -> SEM_FILTER('EV or hybrid battery, charging, high-voltage, drive, drivetrain, or control-software recall') -> GROUP_BY([make], related_ev_hybrid_recall_count=COUNT_DISTINCT(campaign.number));
JOIN(left=COMPLAINTS, right=RECALLS, condition=make equality) -> ORDER_BY(ev_hybrid_complaint_count DESC, make ASC) -> LIMIT(5)

COMPLAINT_BASE := SCAN_TABLE(NHTSA, complaints, [complaint_id,vehicle_id,component_id,summary_text]) -> FILTER(component_id='AIRBAG');
RECALL_BASE := SCAN_DOCS(NHTSA, recalls, [campaign.number,vehicle.vehicle_id AS vehicle_id,component.component_id,remedy.corrective_action]) -> FILTER(component.component_id='AIRBAG');
COMPLAINT_KEYS := COMPLAINT_BASE -> PROJECT([vehicle_id]) -> DEDUP([vehicle_id]);
RECALL_KEYS := RECALL_BASE -> PROJECT([vehicle_id]) -> DEDUP([vehicle_id]);
COMMON_KEYS := JOIN(left=COMPLAINT_KEYS, right=RECALL_KEYS, condition=vehicle_id equality) -> PROJECT([vehicle_id]) -> DEDUP([vehicle_id]);
COMPLAINTS := JOIN(left=COMPLAINT_BASE, right=COMMON_KEYS, condition=vehicle_id equality) -> SEM_FILTER('serious airbag non-deployment, unintended deployment, inflator rupture, shrapnel, or deployment hazard');
RECALLS := JOIN(left=RECALL_BASE, right=COMMON_KEYS, condition=vehicle_id equality) -> SEM_FILTER('remedy replaces an airbag inflator, module, or inflator assembly');
JOIN(left=COMPLAINTS, right=RECALLS, condition=vehicle_id equality) -> GROUP_BY([], n=COUNT_DISTINCT(campaign.number))

COMPLAINT_BASE := SCAN_TABLE(NHTSA, complaints, [complaint_id,make,model,model_year,vehicle_id,component_id,summary_text]) -> FILTER(make='TESLA' AND model='MODEL 3' AND model_year IN [2020,2021,2022]);
RECALL_BASE := SCAN_DOCS(NHTSA, recalls, [recall_id,vehicle.vehicle_id AS vehicle_id,component.component_id AS component_id,risk.defect_summary]) -> FILTER(vehicle.make='TESLA' AND vehicle.model='MODEL 3' AND vehicle.model_year IN [2020,2021,2022]);
COMPLAINT_KEYS := COMPLAINT_BASE -> PROJECT([vehicle_id,component_id]) -> DEDUP([vehicle_id,component_id]);
RECALL_KEYS := RECALL_BASE -> PROJECT([vehicle_id,component_id]) -> DEDUP([vehicle_id,component_id]);
COMMON_KEYS := JOIN(left=COMPLAINT_KEYS, right=RECALL_KEYS, condition=vehicle_id and component_id equality) -> PROJECT([vehicle_id,component_id]) -> DEDUP([vehicle_id,component_id]);
COMPLAINTS := JOIN(left=COMPLAINT_BASE, right=COMMON_KEYS, condition=vehicle_id and component_id equality) -> SEM_FILTER('unintended acceleration or stuck accelerator pedal event');
RECALLS := JOIN(left=RECALL_BASE, right=COMMON_KEYS, condition=vehicle_id and component_id equality) -> SEM_FILTER('accelerator-pedal or speed-control defect');
JOIN(left=COMPLAINTS, right=RECALLS, condition=vehicle_id and component_id equality) -> GROUP_BY([], n=COUNT_DISTINCT(complaint_id,recall_id))

RECALLS := SCAN_DOCS(NHTSA, recalls, [recall_id,campaign.number,vehicle.vehicle_id AS vehicle_id,component.component_id AS component_id,campaign.report_received_date,risk.defect_summary]) -> FILTER(campaign.report_received_date IS NOT NULL AND campaign.report_received_date<>'');
COMPLAINTS := SCAN_TABLE(NHTSA, complaints, [complaint_id,vehicle_id,component_id,received_date,summary_text]);
PAIRS := JOIN(left=COMPLAINTS, right=RECALLS, condition=vehicle_id and component_id equality AND complaint.received_date<recall.report_received_date AND date difference>=1500 days);
NEEDED_RECALLS := PAIRS -> PROJECT([recall_id,campaign.number,risk.defect_summary]) -> DEDUP([recall_id]) -> SEM_EXTRACT('short recall root-cause phrase');
WITH_CAUSE := JOIN(left=PAIRS, right=NEEDED_RECALLS, condition=recall_id equality);
WITH_CAUSE -> SEM_FILTER('complaint and recall describe the same defect mechanism') -> PROJECT([complaint_id,campaign_number,days_between,defect_root_cause])

PAIRS := SCAN_TABLE(NHTSA, complaints, [complaint_id,make,component_id,summary_text]) -> FILTER(make='FORD' AND component_id='AIRBAG') -> SEM_JOIN('same Ford airbag failure mechanism', right=(SCAN_DOCS(NHTSA, recalls, [campaign.number,vehicle.make,component.component_id,risk.defect_summary,remedy.corrective_action]) -> FILTER(vehicle.make='FORD' AND component.component_id='AIRBAG'))) -> SEM_FILTER('concrete airbag safety event');
COMPLAINTS := PAIRS -> PROJECT([complaint_id,summary_text]) -> DEDUP([complaint_id]) -> SEM_CLASSIFY('complaint severity');
CAMPAIGNS := PAIRS -> PROJECT([campaign.number,remedy.corrective_action]) -> DEDUP([campaign.number]) -> SEM_CLASSIFY('recall remedy style');
LABELED_PAIRS := JOIN(left=PAIRS, right=COMPLAINTS, condition=PAIRS.complaint_id = COMPLAINTS.complaint_id);
JOIN(left=LABELED_PAIRS, right=CAMPAIGNS, condition=LABELED_PAIRS.campaign.number = CAMPAIGNS.campaign.number) -> GROUP_BY([campaign.number], matched_complaint_count=COUNT_DISTINCT(complaint_id)) -> ORDER_BY(matched_complaint_count DESC) -> LIMIT(5)

PAIRS := SCAN_TABLE(NHTSA, complaints, [complaint_id,make,component_id,summary_text]) -> FILTER(make='TESLA' AND component_id='ADAS') -> SEM_JOIN('same Tesla ADAS problem', right=(SCAN_DOCS(NHTSA, recalls, [campaign.number,vehicle.make,component.component_id,risk.defect_summary]) -> FILTER(vehicle.make='TESLA' AND component.component_id='ADAS'))) -> SEM_FILTER('driving-context ADAS safety issue') -> SEM_CLASSIFY('dominant ADAS defect topic');
ISSUES := PAIRS -> GROUP_BY([campaign.number,group], matched_complaint_count=COUNT_DISTINCT(complaint_id), complaint_texts=COLLECT(summary_text), recall_texts=COLLECT(risk.defect_summary));
REPORTS := SCAN_DOCS(NHTSA, investigation_reports, [file_id,body]) -> FILTER(body CONTAINS 'Tesla' OR body CONTAINS 'Autopilot' OR body CONTAINS 'driver assistance');
MATCHED := SEM_JOIN(left=ISSUES, right=REPORTS, instruction='same ADAS safety issue or ODI human-factors concern');
MATCHED -> GROUP_BY([campaign.number], matched_complaint_count=MAX(matched_complaint_count), dominant_adas_topic=MODE(group), related_report_ids=COLLECT_DISTINCT(file_id))

REPORTS := SCAN_DOCS(NHTSA, investigation_reports, [file_id,body]) -> PROJECT(cited_recall_cores=NORMALIZE(REGEXP_EXTRACT_ALL(body,'NHTSA recall-number pattern'))) -> GROUP_BY([], cited=COLLECT_DISTINCT(cited_recall_cores));
COMPLAINTS := SCAN_TABLE(NHTSA, complaints, [complaint_id,make,component_id,summary_text]) -> FILTER(make IN ['FORD','JEEP','HONDA','TESLA']);
RECALLS := SCAN_DOCS(NHTSA, recalls, [campaign.number,vehicle.make,component.component_id,risk.defect_summary]) -> FILTER(vehicle.make IN ['FORD','JEEP','HONDA','TESLA']);
MATCHES := SEM_JOIN(left=COMPLAINTS, right=RECALLS, instruction='same make/component and same underlying defect');
BY_MAKE := MATCHES -> GROUP_BY([make], corroborated_complaint_count=COUNT_DISTINCT(complaint_id));
RECALL_COUNTS := RECALLS -> GROUP_BY([make], recall_campaign_count=COUNT_DISTINCT(campaign.number), cores=COLLECT_DISTINCT(core(campaign.number)));
JOIN(left=BY_MAKE, right=RECALL_COUNTS, condition=make equality) -> JOIN(cross, right=REPORTS) -> PROJECT([make,corroborated_complaint_count,recall_campaign_count,alignment_label])

PAIRS := SCAN_TABLE(NHTSA, complaints, [complaint_id,make,component_id,summary_text]) -> FILTER(make='ACURA' AND component_id='BRAKES') -> SEM_JOIN('same Acura braking defect', right=(SCAN_DOCS(NHTSA, recalls, [campaign.number,vehicle.make,component.component_id,risk.defect_summary,risk.consequence_summary]) -> FILTER(vehicle.make='ACURA' AND component.component_id='BRAKES'))) -> SEM_FILTER('real braking-performance safety issue');
FAILURES := PAIRS -> SEM_EXTRACT('dominant braking failure mode');
CAMPAIGNS := PAIRS -> PROJECT([campaign.number,risk.consequence_summary]) -> DEDUP([campaign.number]) -> SEM_CLASSIFY('recall severity');
JOIN(left=FAILURES, right=CAMPAIGNS, condition=FAILURES.campaign.number = CAMPAIGNS.campaign.number) -> GROUP_BY([campaign.number], matched_complaint_count=COUNT_DISTINCT(complaint_id)) -> ORDER_BY(matched_complaint_count DESC) -> LIMIT(3)

COMPLAINTS := SCAN_TABLE(NHTSA, complaints, [complaint_id,make,component_id,summary_text])
  -> FILTER(make='CHEVROLET' AND component_id='BRAKES');
RECALLS := SCAN_DOCS(NHTSA, recalls, [campaign.number,vehicle.make AS make,component.component_id AS component_id,risk.defect_summary,risk.consequence_summary])
  -> FILTER(vehicle.make='CHEVROLET' AND component.component_id='BRAKES');
PAIRS := SEM_JOIN(left=COMPLAINTS, right=RECALLS, instruction='match a complaint and recall only when they describe the same Chevrolet braking defect or risk');
QUALIFIED := PAIRS
  -> SEM_EXTRACT('Extract the shared braking defect theme in at most eight words', {defect_theme:string})
  -> SEM_FILTER('the matched evidence describes a braking safety risk with potential crash, loss-of-control, or extended-stopping consequence');
THEMES := QUALIFIED
  -> GROUP_BY([defect_theme], {matched_complaint_count:COUNT_DISTINCT(complaint_id),distinct_campaign_count:COUNT_DISTINCT(campaign.number),complaint_texts:COLLECT_DISTINCT(summary_text),recall_texts:COLLECT_DISTINCT(risk.defect_summary)});
REPORTS := SCAN_DOCS(NHTSA, investigation_reports, selector='*.txt', columns=[file_id,body])
  -> FILTER(body CONTAINS 'Chevrolet' OR body CONTAINS 'GM' OR body CONTAINS 'brake');
REPORT_MATCHES := SEM_JOIN(left=THEMES, right=REPORTS, instruction='match a canonical braking theme to a report only when the report discusses the same Chevrolet or GM braking issue or ODI risk');
GROUPED := REPORT_MATCHES
  -> GROUP_BY([defect_theme], {matched_complaint_count:MAX(matched_complaint_count),distinct_campaign_count:MAX(distinct_campaign_count),related_report_ids:COLLECT_DISTINCT_SORTED(file_id,'asc'),report_bodies:COLLECT_DISTINCT(body)});
GROUPED
  -> SEM_AGGREGATE('Summarize the ODI braking risk finding for this defect theme in one short phrase', {odi_risk_summary:string}, group_by=[defect_theme], input_bindings={reports:report_bodies})
  -> ORDER_BY([matched_complaint_count DESC,defect_theme ASC])
  -> LIMIT(5)
  -> PROJECT([rank=ROW_NUMBER(),defect_theme,matched_complaint_count,distinct_campaign_count,related_report_ids,odi_risk_summary])

PAIRS := SCAN_TABLE(NHTSA, complaints, [complaint_id,make,component_id,summary_text]) -> FILTER(make='CHRYSLER' AND component_id='AIRBAG') -> SEM_JOIN('same Chrysler airbag defect', right=(SCAN_DOCS(NHTSA, recalls, [campaign.number,vehicle.make,component.component_id,risk.defect_summary,risk.consequence_summary,remedy.corrective_action]) -> FILTER(vehicle.make='CHRYSLER' AND component.component_id='AIRBAG'))) -> SEM_FILTER('airbag safety risk') -> SEM_CLASSIFY('dominant airbag failure mode');
CAMPAIGNS := PAIRS -> GROUP_BY([campaign.number,group], matched_complaint_count=COUNT_DISTINCT(complaint_id), remedy=MIN(remedy.corrective_action), pair_evidence=COLLECT(summary_text,risk.defect_summary));
REPORTS := SCAN_DOCS(NHTSA, investigation_reports, [file_id,body]) -> FILTER(body CONTAINS 'Chrysler' OR body CONTAINS 'airbag' OR body CONTAINS 'inflator');
MATCHED := SEM_JOIN(left=CAMPAIGNS, right=REPORTS, instruction='same Chrysler airbag risk or ODI evidence');
GROUPED := MATCHED -> GROUP_BY([campaign.number], matched_complaint_count=MAX(matched_complaint_count), failure_mode=MODE(group), reports=COLLECT(body), remedy=MIN(remedy));
GROUPED -> SEM_AGGREGATE('dominant remedy style and short ODI evidence summary')

Y2019 := SCAN_TABLE(SEC10K, CSV/2019.csv, [cik,text,word_count]) -> GROUP_BY([cik], primary_text_2019=MAX_BY(text,word_count));
Y2023 := SCAN_TABLE(SEC10K, CSV/2023.csv, [cik,text,word_count]) -> GROUP_BY([cik], primary_text_2023=MAX_BY(text,word_count));
COMMON := JOIN(left=Y2019, right=Y2023, condition=Y2019.cik = Y2023.cik);
M2019 := COMMON -> SCAN_DOCS(SEC10K, primary_text_2019) -> SEM_CLASSIFY('2019 primary revenue model');
M2023 := COMMON -> SCAN_DOCS(SEC10K, primary_text_2023) -> SEM_CLASSIFY('2023 primary revenue model');
JOIN(left=M2019, right=M2023, condition=cik equality) -> FILTER(models are determined and changed) -> GROUP_BY([transition], count=COUNT(*)) -> ORDER_BY(count DESC) -> LIMIT(10)

Y2019 := SCAN_TABLE(SEC10K, CSV/2019.csv, [cik,text]);
Y2023 := SCAN_TABLE(SEC10K, CSV/2023.csv, [cik,text,word_count]) -> GROUP_BY([cik], primary_text=MAX_BY(text,word_count));
COMMON := JOIN(left=Y2019, right=Y2023, condition=Y2019.cik = Y2023.cik);
LEFT := COMMON -> SCAN_DOCS(SEC10K, Y2019.text) -> SEM_FILTER('challenger in 2019');
RIGHT := COMMON -> SCAN_DOCS(SEC10K, Y2023.primary_text) -> SEM_FILTER('recognized leader in 2023') -> SEM_EXTRACT('2023 company legal name and industry sector');
JOIN(left=LEFT, right=RIGHT, condition=cik equality) -> PROJECT([company_name,industry_sector])

Y2019 := SCAN_TABLE(SEC10K, CSV/2019.csv, [cik,text]);
Y2023 := SCAN_TABLE(SEC10K, CSV/2023.csv, [cik,text,word_count]) -> GROUP_BY([cik], primary_text=MAX_BY(text,word_count));
COMMON := JOIN(left=Y2019, right=Y2023, condition=Y2019.cik = Y2023.cik);
LEFT := COMMON -> SCAN_DOCS(SEC10K, Y2019.text) -> SEM_FILTER('early-stage or emerging competitor in 2019') -> SEM_EXTRACT('2019 employee count');
RIGHT := COMMON -> SCAN_DOCS(SEC10K, Y2023.primary_text) -> SEM_FILTER('recognized leader in 2023') -> SEM_EXTRACT('2023 company name, sector, and employee count');
JOIN(left=LEFT, right=RIGHT, condition=cik equality) -> PROJECT([company_name,industry_sector,employee_count_2019,employee_count_2023])

Y2019 := SCAN_TABLE(SEC10K, CSV/2019.csv, [cik,text]);
Y2023 := SCAN_TABLE(SEC10K, CSV/2023.csv, [cik,text,word_count]) -> GROUP_BY([cik], primary_text=MAX_BY(text,word_count));
COMMON := JOIN(left=Y2019, right=Y2023, condition=Y2019.cik = Y2023.cik);
LEFT := COMMON -> SCAN_DOCS(SEC10K, Y2019.text) -> SEM_EXTRACT('company-wide employee count in 2019') -> FILTER(employee_count_2019>=1000);
RIGHT := COMMON -> SCAN_DOCS(SEC10K, Y2023.primary_text) -> SEM_EXTRACT('2023 company name and company-wide employee count');
JOIN(left=LEFT, right=RIGHT, condition=cik equality) -> PROJECT(employee_change_percent) -> ORDER_BY(employee_change_percent) -> LIMIT(10)

B2021 := SCAN_TABLE(SEC10K, CSV/2021.csv, [cik,text,word_count]) -> FILTER(word_count>60000) -> GROUP_BY([cik], text=MAX_BY(text,word_count));
B2023 := SCAN_TABLE(SEC10K, CSV/2023.csv, [cik,text,word_count]) -> FILTER(word_count>60000) -> GROUP_BY([cik], text=MAX_BY(text,word_count));
COMMON := JOIN(left=B2021, right=B2023, condition=B2021.cik = B2023.cik);
DOMESTIC := COMMON -> SCAN_DOCS(SEC10K, B2021.text) -> SEM_CLASSIFY('2021 geographic footprint') -> FILTER(footprint='domestic_only') -> SEM_FILTER('no foreign-currency risk');
GLOBAL := COMMON -> SCAN_DOCS(SEC10K, B2023.text) -> SEM_FILTER('foreign-currency risk disclosed') -> SEM_CLASSIFY('2023 geographic footprint') -> FILTER(footprint='globally_diversified');
TRANSITIONS := JOIN(left=DOMESTIC, right=GLOBAL, condition=cik equality);
TRANSITIONS -> SEM_CLASSIFY('2023 growth strategy') -> SEM_EXTRACT('2023 company name, sector, countries') -> ORDER_BY(foreign_country_count DESC) -> LIMIT(10)
